mapper.select:
SELECT m.id, m.conversation_id, m.sender_id, u.username AS sender_name, u.avatar AS sender_avatar, m.type, m.content, m.image_url, m.send_time, m.seq, m.is_recalled AS recalled FROM im_message m JOIN sys_user u ON u.id = m.sender_id WHERE m.conversation_id = #{conversationId}
AND m.seq < #{beforeSeq}
ORDER BY m.seq DESC LIMIT #{limit}

SELECT * FROM im_message
WHERE conversation_id = #{conversationId}
  AND seq > #{sinceSeq}
  AND is_recalled = 0
ORDER BY seq ASC
LIMIT 200

mapper.update:
UPDATE im_message
SET is_recalled = 1
WHERE id        = #{messageId}
  AND sender_id = #{senderId}
  AND send_time > DATE_SUB(NOW(), INTERVAL 120 SECOND)
